import{_ as o,a0 as p,w as a,s as r,I as e,x as i,a1 as l,A as n,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"使用 Cockpit 方便地管理容器 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Cockpit 方便地管理容器 | LCTT (201705) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Cockpit 方便地管理容器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Cockpit 方便地管理容器 | LCTT (201705) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201705/20170317 Make Container Management Easy With Cockpit","title":"使用 Cockpit 方便地管理容器","tag":"201705","desc":""},"relativePath":"201705/20170317 Make Container Management Easy With Cockpit.md","filePath":"[post].md"}'),k={name:"201705/20170317 Make Container Management Easy With Cockpit.md"};function u(g,t,c,h,b,m){const s=p("Link");return a(),r("div",null,[t[34]||(t[34]=e("h1",{id:"使用-cockpit-方便地管理容器",tabindex:"-1"},[i("使用 Cockpit 方便地管理容器 "),e("a",{class:"header-anchor",href:"#使用-cockpit-方便地管理容器","aria-label":"Permalink to “使用 Cockpit 方便地管理容器”"},"​")],-1)),t[35]||(t[35]=e("p",null,[e("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/cockpit-containers.jpg?itok=D3MMNlkg",alt:"cockpit",title:"cockpit"})],-1)),t[36]||(t[36]=e("blockquote",null,[e("p",null,"如果你正在尋找一種管理運行容器的 Linux 服務器的簡單方法，那麼你應該看看 Cockpit。")],-1)),e("p",null,[t[3]||(t[3]=i("如果你管理着一台 Linux 服務器，那麼你可能正在尋找一個可靠的管理工具。為了這個你可能已經看了 ",-1)),l(s,{href:"http://www.webmin.com/"},{default:n(()=>[...t[0]||(t[0]=[i("Webmin",-1)])]),_:1}),t[4]||(t[4]=i(" 和 ",-1)),l(s,{href:"http://cpanel.com/"},{default:n(()=>[...t[1]||(t[1]=[i("cPanel",-1)])]),_:1}),t[5]||(t[5]=i(" 這類軟件。但是，如果你正在尋找一種簡單的方法來管理還包括了 Docker 的 Linux 服務器，那麼有一個工具可以用於這個需求：",-1)),l(s,{href:"http://cockpit-project.org/"},{default:n(()=>[...t[2]||(t[2]=[i("Cockpit",-1)])]),_:1}),t[6]||(t[6]=i("。",-1))]),t[37]||(t[37]=e("p",null,"為什麼使用 Cockpit？因為它可以處理這些管理任務：",-1)),t[38]||(t[38]=e("ul",null,[e("li",null,"連接並管理多台機器"),e("li",null,"通過 Docker 管理容器"),e("li",null,"與 Kubernetes 或 Openshift 集羣進行交互"),e("li",null,"修改網絡設置"),e("li",null,"管理用户帳號"),e("li",null,"通過基於 Web 的 shell 訪問"),e("li",null,"通過圖表查看系統性能信息"),e("li",null,"查看系統服務和日誌文件")],-1)),e("p",null,[t[12]||(t[12]=i("Cockpit 可以安裝在 ",-1)),l(s,{href:"https://www.debian.org/"},{default:n(()=>[...t[7]||(t[7]=[i("Debian",-1)])]),_:1}),t[13]||(t[13]=i("、",-1)),l(s,{href:"https://www.redhat.com/en"},{default:n(()=>[...t[8]||(t[8]=[i("Red Hat",-1)])]),_:1}),t[14]||(t[14]=i("、",-1)),l(s,{href:"https://www.centos.org/"},{default:n(()=>[...t[9]||(t[9]=[i("CentOS",-1)])]),_:1}),t[15]||(t[15]=i("、",-1)),l(s,{href:"https://www.archlinux.org/"},{default:n(()=>[...t[10]||(t[10]=[i("Arch Linux",-1)])]),_:1}),t[16]||(t[16]=i(" 和 ",-1)),l(s,{href:"https://www.ubuntu.com/"},{default:n(()=>[...t[11]||(t[11]=[i("Ubuntu",-1)])]),_:1}),t[17]||(t[17]=i(" 之上。在這裏，我將使用一台已經安裝了 Docker 的 Ubuntu 16.04 服務器來安裝系統。",-1))]),t[39]||(t[39]=d(`<p>在上面的功能列表中，其中最突出的是容器管理。為什麼？因為它使安裝和管理容器變得非常簡單。事實上，你可能很難找到更好的容器管理解決方案。</p><p>因此，讓我們來安裝這個方案並看看它的使用是多麼簡單。</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>正如我前面提到的，我將在一台運行着 Docker 的 Ubuntu 16.04 實例上安裝 Cockpit。安裝步驟很簡單。你要做的第一件事是登錄你的 Ubuntu 服務器。接下來，你必須使用下面的命令添加必要的倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:cockpit-project/cockpit</span></span></code></pre></div><p>出現提示時，按下鍵盤上的回車鍵，等待提示返回。一旦返回到 bash 提示符，使用下面的命令來更新 apt：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get get update</span></span></code></pre></div><p>使用下面的命令安裝 Cockpit：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get -y install cockpit cockpit-docker</span></span></code></pre></div><p>安裝完成後，需要啓動 Cockpit 服務並使它開機自動啓動。要做到這個，使用下面的兩個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl start cockpit</span></span>
<span class="line"><span>sudo systemctl enable cockpit</span></span></code></pre></div><p>安裝就到這裏了。</p><h3 id="登錄到-cockpit" tabindex="-1">登錄到 Cockpit <a class="header-anchor" href="#登錄到-cockpit" aria-label="Permalink to “登錄到 Cockpit”">​</a></h3><p>要訪問 Cockpit 的 web 界面，打開瀏覽器（與 Cockpit 服務器在同一個網絡內），輸入 <code>http://IP_OF_SERVER:9090</code>，你就會看到登錄頁面（圖 1）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/cockpit_a.jpg?itok=RViOst2V" alt="login" title="login"></p><p><em>圖 1：Cockpit 登錄頁面。</em></p><p>在 Ubuntu 中使用 Cockpit 有個警告。Cockpit 中的很多任務需要管理員權限。如果你使用普通用户登錄，則無法使用 Docker 等一些工具。 要解決這個問題，你可以在 Ubuntu 上啓用 root 用户。但這並不總是一個好主意。通過啓用 root 帳户，你將繞過已經建立多年的安全系統。但是，在本文的用途中，我將使用以下兩個命令啓用 root 用户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo passwd root</span></span>
<span class="line"><span>sudo passwd -u root</span></span></code></pre></div><p>注意，請確保給 root 帳户一個強壯的密碼。</p><p>你想恢復這個修改的話，你只需輸入下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo passwd -l root</span></span></code></pre></div><p>在其他發行版（如 CentOS 和 Red Hat）中，你可以使用用户名 <code>root</code> 及其密碼登錄 Cockpit，而無需像上面那樣需要額外的步驟。</p><p>如果你對啓用 root 用户感到擔心，則可以在服務器的終端窗口拉取鏡像（使用命令 <code>docker pull IMAGE_NAME</code>， 這裏的 <code>IMAGE_NAME</code> 是你要拉取的鏡像）。這會將鏡像添加到你的 docker 服務器中，然後可以通過普通用户進行管理。唯一需要注意的是，普通用户必須使用以下命令將自己添加到 Docker 組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo usermod -aG docker USER</span></span></code></pre></div><p>其中，<code>USER</code> 是實際添加到組的用户名。在你完成後，重新登出並登入，接着使用下面的命令重啓 Docker：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo service docker restart</span></span></code></pre></div><p>現在常規用户可以啓動並停止 Docker 鏡像/容器而無需啓用 root 用户了。唯一一點是用户不能通過 Cockpit 界面添加新的鏡像。</p><h3 id="使用-cockpit" tabindex="-1">使用 Cockpit <a class="header-anchor" href="#使用-cockpit" aria-label="Permalink to “使用 Cockpit”">​</a></h3><p>一旦你登錄後，你可以看到 Cockpit 的主界面（圖 2）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/cockpit_b.jpg?itok=tZCHcq-Y" alt="main window" title="main window"></p><p><em>圖 2：Cockpit 主界面。</em></p><p>你可以通過每個欄目來檢查服務器的狀態等，但是我們想要直接進入容器。單擊 “Containers” 那欄以顯示當前運行的以及可用的鏡像（圖3）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/cockpit_c.jpg?itok=OOYJt2yv" alt="Cockpit" title="Cockpit"></p><p><em>圖 3：使用 Cockpit 管理容器難以置信地簡單。</em></p><p>要啓動一個鏡像，只要找到鏡像並點擊關聯的啓動按鈕。在彈出的窗口中（圖 4），你可以在點擊運行之前查看所有鏡像的信息（並根據需要調整）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/cockpit_d.jpg?itok=8uldEq_r" alt="Running Docker image" title="Running Docker image"></p><p><em>圖 4： 使用 Cockpit 運行 Docker 鏡像。</em></p><p>鏡像運行後，你可以點擊它查看狀態，並可以停止、重啓、刪除實例。你也可以點擊修改資源限制並接着調整內存限制還有（或者）CPU 優先級。</p><h3 id="添加新的鏡像" tabindex="-1">添加新的鏡像 <a class="header-anchor" href="#添加新的鏡像" aria-label="Permalink to “添加新的鏡像”">​</a></h3><p>假設你以 root 用户身份登錄。如果是這樣，那麼你可以在 Cockpit GUI 的幫助下添加新的鏡像。在“ Container” 欄目下，點擊獲取新的鏡像按鈕，然後在新的窗口中搜索要添加的鏡像。假設你要添加 CentOS 的最新官方版本。在搜索欄中輸入 centos，在得到搜索結果後，選擇官方列表，然後單擊下載（圖5）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/cockpit_f.jpg?itok=_S5g8Da2" alt="Adding image" title="Adding image"></p><p><em>圖 5：使用 Cockpit 添加最新的官方構建 CentOS 鏡像到 Docker 中。</em></p><p>鏡像下載完後，那它就在 Docker 中可用了，並可以通過 Cockpit 運行。</p><h3 id="如獲取它那樣簡單" tabindex="-1">如獲取它那樣簡單 <a class="header-anchor" href="#如獲取它那樣簡單" aria-label="Permalink to “如獲取它那樣簡單”">​</a></h3><p>管理 Docker 並不容易。是的，在 Ubuntu 上運行 Cockpit 會有一個警告，但如果這是你唯一的選擇，那麼也有辦法讓它工作。在 Cockpit 的幫助下，你不僅可以輕鬆管理 Docker 鏡像，也可以在任何可以訪問 Linux 服務器的 web 瀏覽器上這樣做。請享受這個新發現的讓 Docker 易用的方法。</p>`,45)),e("p",null,[e("em",null,[t[19]||(t[19]=i("在 Linux Foundation 以及 edX 中通過免費的 ",-1)),l(s,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:n(()=>[...t[18]||(t[18]=[i('"Introduction to Linux"',-1)])]),_:1}),t[20]||(t[20]=i(" 課程學習 Linux。",-1))])]),t[40]||(t[40]=e("hr",null,null,-1)),e("p",null,[t[22]||(t[22]=i("via: ",-1)),l(s,{href:"https://www.linux.com/learn/intro-to-linux/2017/3/make-container-management-easy-cockpit"},{default:n(()=>[...t[21]||(t[21]=[i("https://www.linux.com/learn/intro-to-linux/2017/3/make-container-management-easy-cockpit",-1)])]),_:1})]),e("p",null,[t[26]||(t[26]=i("作者：",-1)),l(s,{href:"https://www.linux.com/users/jlwallen"},{default:n(()=>[...t[23]||(t[23]=[i("JACK WALLEN",-1)])]),_:1}),t[27]||(t[27]=i(" 譯者：",-1)),l(s,{href:"https://github.com/geekpi"},{default:n(()=>[...t[24]||(t[24]=[i("geekpi",-1)])]),_:1}),t[28]||(t[28]=i(" 校對：",-1)),l(s,{href:"https://github.com/jasminepeng"},{default:n(()=>[...t[25]||(t[25]=[i("jasminepeng",-1)])]),_:1})]),e("p",null,[t[31]||(t[31]=i("本文由 ",-1)),l(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[29]||(t[29]=[i("LCTT",-1)])]),_:1}),t[32]||(t[32]=i(" 原創編譯，",-1)),l(s,{href:"https://linux.cn/"},{default:n(()=>[...t[30]||(t[30]=[i("Linux中國",-1)])]),_:1}),t[33]||(t[33]=i(" 榮譽推出",-1))])])}const x=o(k,[["render",u]]);export{w as __pageData,x as default};
